function makeField(cell,label,index,total){var field=document.createElement('div');field.className='dior-mobile-record-field';field.setAttribute('data-column-index',String(index));var heading=document.createElement('span');heading.className='dior-mobile-record-label';heading.textContent=label||(index===total-1?'Actions':'Details');field.appendChild(heading);var value=document.createElement('div');value.className='dior-mobile-record-value';var clone=cell.cloneNode(!0);removeIds(clone);clone.querySelectorAll('button, a, input, select, textarea').forEach(function(control){control.remove()});value.innerHTML=clone.innerHTML;value.querySelectorAll('[style]').forEach(function(el){el.style.maxWidth='100%';el.style.whiteSpace='normal';el.style.overflowWrap='anywhere'});field.appendChild(value);return field}
function makeSelection(cell,card){var source=cell.querySelector('input[type="checkbox"]');if(!source)return;var line=document.createElement('div');line.className='dior-mobile-record-select';var proxy=document.createElement('input');proxy.type='checkbox';proxy.className='form-check-input';proxy.checked=source.checked;proxy.disabled=source.disabled;proxy.setAttribute('aria-label','Select record');var label=document.createElement('span');label.textContent='Select record';proxy.addEventListener('change',function(){if(source.checked!==proxy.checked)source.click();window.setTimeout(function(){card.closest('.dior-mobile-cards').querySelectorAll('.dior-mobile-record-select input[type="checkbox"]').forEach(function(check){var sourceRow=check.closest('.dior-mobile-record-card');var index=Number(sourceRow&&sourceRow.getAttribute('data-row-index'));var row=card._diorSourceTable&&card._diorSourceTable.querySelectorAll('tbody tr')[index];var original=row&&row.querySelector('input[type="checkbox"]');if(original)check.checked=original.checked})},0)});line.appendChild(proxy);line.appendChild(label);card.appendChild(line)}
