function init(){document.querySelectorAll(rootSelector).forEach(function(root){root.querySelectorAll(tableSelector).forEach(prepareTable);installDoctorMobileNavigation(root)})}
function boot(){init();var observer=new MutationObserver(function(mutations){var hasNewTables=mutations.some(function(mutation){return Array.prototype.some.call(mutation.addedNodes||[],function(node){return node.nodeType===1&&(node.matches&&node.matches(tableSelector)||node.querySelector&&node.querySelector(tableSelector))})});if(hasNewTables)init()});observer.observe(document.documentElement,{childList:!0,subtree:!0})}
